"""Private owner-facing JRA Web racecard schedule and manual matching progress."""
HTML = "<section id=\"jraPrestartSection\"><h2>JRA前日出馬表・馬番照合の進み具合</h2><p class=\"hint\">前日予想では、開催当日以降のPDFよりもJRAのWeb出馬表を先に確認するで。通常はレース前日10時すぎに馬番が発表される。GI・一部重賞は時刻が異なり、掲載まで時間差もある。</p><a href=\"https://www.jra.go.jp/keiba/\" target=\"_blank\" rel=\"noopener noreferrer\" id=\"jraOfficialWebLink\">JRA公式の「出馬表」メニューを開く</a><p class=\"hint\" id=\"jraPublishTiming\">開催日を選ぶと通常の発表目安を表示するで。</p><p id=\"jraNumberProgress\" class=\"hint\">本人が入力した馬番の照合状況を表示するで。</p><div id=\"jraRaceChecklist\" role=\"region\" aria-label=\"JRA手入力馬番照合の進行状況\"></div><p class=\"warning\">この進行状況はJRDB想定馬名と本人が転記した馬名の一致だけ。JRA公式データの自動取得・取消・最新馬場の検証・予想生成を示すものではありません。</p></section>"
CSS = "#jraPrestartSection #jraOfficialWebLink{display:block;border:1px solid #dcbd75;border-radius:10px;padding:12px;margin:12px 0;font-weight:750}#jraRaceChecklist{display:grid;grid-template-columns:repeat(auto-fit,minmax(135px,1fr));gap:8px}#jraRaceChecklist button{padding:9px;margin:0;background:#304660;color:#f2f4f8;min-height:47px;text-align:left;font-size:13px}#jraRaceChecklist button.typed-ok{border:1px solid #9bc4a6}#jraRaceChecklist button.needs-work{border:1px solid #a68863}"
JS = "'use strict';\n// JRA's usual publishing schedule and private progress are NOT a live\n// official-racecard fetch. No horse numbers leave this browser.\n(function(){\n const MAIL='keiba-nine-jrdb-personal-mail-v1';\n const MANUAL='keiba-nine-owner-manual-numbers-v1';\n const $=id=>document.getElementById(id);\n const picker=$('chooseMeeting'),timing=$('jraPublishTiming'),\n       progress=$('jraNumberProgress'),list=$('jraRaceChecklist');\n const officialWebLink=$('jraOfficialWebLink');\n function readLocal(key){\n  try{const a=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(a)?a:[];}\n  catch(_){return [];}\n }\n function standardPublication(date){\n  if(!/^\\d{4}-\\d{2}-\\d{2}$/.test(date))return '';\n  const start=new Date(date+'T00:00:00Z');\n  if(Number.isNaN(start.valueOf())||start.toISOString().slice(0,10)!==date)return '';\n  const preceding=new Date(start.valueOf()-86400000).toISOString().slice(0,10);\n  const cutoff=new Date(preceding+'T10:15:00+09:00');\n  const moment=new Date();\n  if(moment.valueOf()<cutoff.valueOf()){\n   return '通常の馬番付き出馬表は '+preceding+' 10時すぎが発表目安やで。発表前でもGIなど例外あり。';\n  }\n  return '通常の発表目安（'+preceding+' 10時すぎ）は過ぎてるで。JRAの出馬表で実際に公開済みか確認してな。';\n }\n function update(){\n  list.replaceChildren();\n  const selected=picker.value;\n  const [day,track]=selected.split('|');\n  if(!day||!track){\n   timing.textContent='まず上の日付と競馬場を選んでな。';\n   progress.textContent='JRDB想定メール未選択。';\n   return;\n  }\n  timing.textContent=standardPublication(day)+' PDF一覧は主に開催当日以降の確認用やで。';\n  const m=readLocal(MAIL).find(v=>v&&v.date===day&&v.track===track&&v.kind==='jrdb-provisional');\n  if(!m||!Array.isArray(m.races)){\n   progress.textContent='この開催の想定メールをまだ取り込んでへんで。';return;\n  }\n  const saved=readLocal(MANUAL);\n  const status={ok:0,missing:0,stale:0,changed:0};\n  const descriptions={ok:'馬名一致（本人転記）',missing:'馬番未入力',stale:'想定更新・再照合',changed:'馬名差異あり'};\n  for(const r of m.races.slice().sort((a,b)=>a.race-b.race)){\n   const exact=saved.find(x=>x&&x.date===day&&x.track===track&&x.race===r.race);\n   let kind='missing';\n   if(exact){\n    if(exact.sourceMark!==JSON.stringify([r.postTime,r.expected,r.horses]))kind='stale';\n    else{\n     const expected=new Set(r.horses);\n     const numbered=Array.isArray(exact.rows)?exact.rows.map(x=>x.name):[];\n     kind=numbered.length===expected.size&&\n      numbered.every(n=>expected.has(n))&&new Set(numbered).size===numbered.length?\n      'ok':'changed';\n    }\n   }\n   status[kind]++;\n   const btn=document.createElement('button');\n   btn.type='button';\n   btn.className=kind==='ok'?'typed-ok':'needs-work';\n   btn.textContent=r.race+'R '+descriptions[kind];\n   btn.onclick=()=>{\n    $('numberRace').value=String(r.race);\n    if(typeof $('numberRace').onchange==='function')$('numberRace').onchange();\n    const section=$('manualNumberSection');\n    if(section&&typeof section.scrollIntoView==='function')\n     section.scrollIntoView({behavior:'smooth',block:'start'});\n   };\n   list.append(btn);\n  }\n  progress.textContent=day+' '+track+'／全'+m.races.length+'R：'\n   +status.ok+'R馬名一致、'+status.missing+'R未入力、'\n   +status.stale+'R再照合、'+status.changed+'R差異あり。'\n   +'すべて本人の手入力メモで、公式確認済みの件数ではないで。';\n }\n const previous=picker.onchange;\n picker.onchange=()=>{if(typeof previous==='function')previous();update()};\n for(const id of ['importMail','deleteMeeting','clearAll','saveNumbers','deleteNumbers']){\n  const element=$(id),prior=element.onclick;\n  element.onclick=function(){\n   const result=typeof prior==='function'?prior.apply(this,arguments):undefined;\n   update();\n   return result;\n  };\n }\n update();\n})();\n"
